    ok = {'L1','L2','L3','L4','L5','L6','L7'}; ex = {'F','P','Pt','N'}
    ly = {'static','statistical','dynamic','strategic','outside-E','outside-X','category','undetermined'}
    bad = [k for k, v in R.items() if v[0] not in ok or v[1] not in ex or v[2] not in ly or not v[3].strip()]
    print(f"{len(R)} items; {len(bad)} incomplete or invalid: {bad[:20]}")
